  const [documentVisible, setDocumentVisible] = useState(() => typeof document === "undefined" || !document.hidden);
  const safeSpeed = clamp(speed, 0, 3);
  const paused = !hostVisible || !documentVisible || safeSpeed === 0;
  const source = useMemo(() => buildFocusedDocument(size, particleAmount), [particleAmount, size]);

  const postControls = useCallback(() => {
    iframeRef.current?.contentWindow?.postMessage({
      type: "generative-tree-controls",
      controls: { speed: safeSpeed, paused },
    }, "*");
  }, [paused, safeSpeed]);

  useEffect(() => {
    const iframe = iframeRef.current;
    if (!iframe || typeof IntersectionObserver === "undefined") return undefined;
    const observer = new IntersectionObserver(([entry]) => setHostVisible(entry?.isIntersecting ?? true));
    observer.observe(iframe);
    return () => observer.disconnect();
  }, []);

  useEffect(() => {
    if (typeof document === "undefined") return undefined;
    const update = () => setDocumentVisible(!document.hidden);
    document.addEventListener("visibilitychange", update);
    return () => document.removeEventListener("visibilitychange", update);
  }, []);

  useEffect(() => {
    postControls();
  }, [postControls, source]);

  return (
    <div
      className={`threeui-background generative-tree${className ? ` ${className}` : ""}`}
      style={{ background: "#0a0a0a", pointerEvents: "auto", ...style }}
    >
      <iframe
        ref={iframeRef}
        title="Generative Tree background"
        srcDoc={source}
        sandbox="allow-scripts"
        onLoad={postControls}
        aria-hidden="true"
        tabIndex={-1}
        style={{
          position: "absolute",
          inset: 0,
          display: "block",
          width: "100%",
          height: "100%",
          border: 0,
          background: "#0a0a0a",
          opacity: clamp(opacity, 0.05, 1),
          filter: `hue-rotate(${clamp(hue, -180, 180)}deg) saturate(${clamp(saturation, 0, 2)}) brightness(${clamp(brightness, 0.35, 1.8)})`,
        }}
      />
    </div>
  );
}

import { useEffect, useRef } from "react";
import { CONDENSATION_DEFAULTS, createCondensationRenderer, type CondensationOptions } from "./condensationRenderer";

export type CondensationBackgroundProps = Partial<CondensationOptions> & { className?: string };
export function CondensationBackground({ className = "", ...props }: CondensationBackgroundProps) {
  const hostRef = useRef<HTMLDivElement>(null), canvasRef = useRef<HTMLCanvasElement>(null), optionsRef = useRef({ ...CONDENSATION_DEFAULTS, ...props }); optionsRef.current = { ...CONDENSATION_DEFAULTS, ...props };
  useEffect(() => { const host = hostRef.current, canvas = canvasRef.current; if (!host || !canvas) return undefined; const renderer = createCondensationRenderer(canvas, () => optionsRef.current); let frame = 0, visible = true;
    const resize = () => { const bounds = host.getBoundingClientRect(); renderer.resize(bounds.width, bounds.height); renderer.render(performance.now()); }; const tick = (now: number) => { renderer.render(now); frame = visible && !document.hidden ? requestAnimationFrame(tick) : 0; }; const resizeObserver = new ResizeObserver(resize), intersection = new IntersectionObserver(([entry]) => { visible = entry?.isIntersecting ?? true; if (visible && !frame) frame = requestAnimationFrame(tick); if (!visible && frame) cancelAnimationFrame(frame), frame = 0; }); resizeObserver.observe(host); intersection.observe(host); resize(); frame = requestAnimationFrame(tick); return () => { if (frame) cancelAnimationFrame(frame); resizeObserver.disconnect(); intersection.disconnect(); renderer.dispose(); };
  }, []);
  return <div ref={hostRef} className={`threeui-background condensation${className ? ` ${className}` : ""}`} style={{ opacity: optionsRef.current.opacity }}><canvas ref={canvasRef} /></div>;
}

export type CondensationOptions = {
  speed: number;
  dropAmount: number;
  opacity: number;
};

export const CONDENSATION_DEFAULTS: CondensationOptions = {
  speed: 1,
  dropAmount: 1,
  opacity: 1,
};

type Drop = {
  x: number;
  y: number;
  r: number;
  rMax: number;
  grow: number;
  running: boolean;
  vy: number;
};

type Splash = {
  x: number;
  y: number;
  r0: number;
  born: number;
};

export function createCondensationRenderer(
  canvas: HTMLCanvasElement,
  getOptions: () => CondensationOptions,
) {
  const context = canvas.getContext("2d");
  if (!context) throw new Error("Condensation requires Canvas 2D");

  let width = 1;
  let height = 1;
  let dpr = 1;
  let floorY = 1;
  let baseMaxDrops = 120;
  let maxDrops = 120;
  let lastCascade = 0;
  let simulatedNow = 0;
  let lastFrame = 0;
  let drops: Drop[] = [];
  let splashes: Splash[] = [];
  const bubbleSprites = new Map<number, HTMLCanvasElement>();

  const getBubbleSprite = (radius: number) => {
    const spriteRadius = Math.max(0.5, Math.round(radius * 2) / 2);
    const cached = bubbleSprites.get(spriteRadius);
    if (cached) return cached;

    const padding = Math.ceil(2 * dpr);
    const size = Math.ceil(spriteRadius * 2 + padding * 2);
    const sprite = document.createElement("canvas");
    sprite.width = size;
    sprite.height = size;
    const spriteContext = sprite.getContext("2d");
    if (!spriteContext) throw new Error("Condensation bubble sprite unavailable");
    const center = size / 2;
    const lit = spriteRadius / (4.4 * dpr);
    spriteContext.fillStyle = `rgba(96,139,196,${0.18 + lit * 0.22})`;
    spriteContext.beginPath();
    spriteContext.arc(center, center, spriteRadius, 0, Math.PI * 2);
    spriteContext.fill();
    spriteContext.strokeStyle = `rgba(70,98,148,${0.35 + lit * 0.35})`;
    spriteContext.lineWidth = 0.9 * dpr;
    spriteContext.stroke();
    spriteContext.fillStyle = `rgba(255,255,255,${0.32 + lit * 0.3})`;
    spriteContext.beginPath();
    spriteContext.arc(
      center - spriteRadius * 0.32,
      center - spriteRadius * 0.36,
      Math.max(0.45 * dpr, spriteRadius * 0.24),
      0,
      Math.PI * 2,
    );
    spriteContext.fill();
    bubbleSprites.set(spriteRadius, sprite);
    return sprite;
  };

  const seedDrop = (headStart = 0) => {
    const margin = 8 * dpr;
    const availableWidth = Math.max(1, width - margin * 2);
    const availableHeight = Math.max(1, floorY - margin * 2);
    drops.push({
      x: margin + Math.random() * availableWidth,
      y: margin + Math.random() * availableHeight,
      r: (0.5 + headStart * 0.7) * dpr,
      rMax: (2.1 + Math.random() * 2.3) * dpr,
      grow: (0.0022 + Math.random() * 0.0032) * dpr,
      running: false,
      vy: 0,
    });
  };

  const resize = (cssWidth: number, cssHeight: number) => {
    dpr = Math.min(window.devicePixelRatio || 1, 2);
    width = canvas.width = Math.max(1, Math.floor(cssWidth * dpr));
    height = canvas.height = Math.max(1, Math.floor(cssHeight * dpr));
    canvas.style.width = `${cssWidth}px`;
    canvas.style.height = `${cssHeight}px`;
    floorY = Math.max(1, height - 2 * dpr);
    baseMaxDrops = Math.max(80, Math.min(240, Math.round((width * height) / (dpr * dpr) / 5200)));
    maxDrops = Math.round(baseMaxDrops * getOptions().dropAmount);
    drops = [];
    splashes = [];
    bubbleSprites.clear();
    const seedCount = Math.round(maxDrops * 0.62);
    for (let index = 0; index < seedCount; index += 1) seedDrop(Math.random() * 3);
  };

  const step = (now: number, motionScale = 1) => {
    if (drops.length < maxDrops && Math.random() < 0.34 * motionScale) seedDrop();
    if (now - lastCascade > 6400) {
      lastCascade = now;
      drops
        .filter((drop) => !drop.running)
        .sort((a, b) => b.r - a.r)
        .slice(0, 3)
        .forEach((drop) => {
          drop.running = true;
          drop.vy = 0.35 * dpr;
        });
    }

    for (let index = drops.length - 1; index >= 0; index -= 1) {
      const drop = drops[index];
      if (!drop.running) {
        drop.r += drop.grow * motionScale;
        if (drop.r >= drop.rMax) {
          drop.running = true;
          drop.vy = 0.3 * dpr;
        }
        continue;
      }

      drop.vy = Math.min(drop.vy + 0.075 * dpr * motionScale, 5.4 * dpr);
      drop.y += drop.vy * motionScale;
      for (let otherIndex = drops.length - 1; otherIndex >= 0; otherIndex -= 1) {
        const other = drops[otherIndex];
        if (other === drop || other.running) continue;
        const overlapsX = Math.abs(other.x - drop.x) < drop.r + other.r + 1.5 * dpr;
        const overlapsY = other.y > drop.y - drop.r && other.y < drop.y + drop.vy + drop.r;
        if (overlapsX && overlapsY) {
          drop.r = Math.sqrt(drop.r * drop.r + other.r * other.r);
          drops.splice(otherIndex, 1);
          if (otherIndex < index) index -= 1;
        }
      }

      if (drop.y >= floorY) {
        splashes.push({ x: drop.x, y: floorY, r0: drop.r, born: now });
        drops.splice(index, 1);
      }
    }
    splashes = splashes.filter((splash) => now - splash.born < 760);
  };

  const draw = (now: number) => {
    context.clearRect(0, 0, width, height);
    drops.forEach((drop) => {
      const sprite = getBubbleSprite(drop.r);
      context.drawImage(sprite, drop.x - sprite.width / 2, drop.y - sprite.height / 2);
    });

    splashes.forEach((splash) => {
      const progress = (now - splash.born) / 760;
      if (progress < 0 || progress > 1) return;
      const radius = splash.r0 + progress * 16 * dpr;
      context.strokeStyle = `rgba(75,108,158,${(1 - progress) * 0.52})`;
      context.lineWidth = 1.1 * dpr;
      context.beginPath();
      context.ellipse(splash.x, splash.y, radius, radius * 0.34, 0, 0, Math.PI * 2);
      context.stroke();
    });
  };

  return {
    resize,
    render(now: number) {
      const options = getOptions();
      maxDrops = Math.round(baseMaxDrops * options.dropAmount);
      const delta = lastFrame ? Math.min(50, now - lastFrame) : 16.67;
      lastFrame = now;
      simulatedNow += delta * options.speed;
      step(simulatedNow, options.speed);
      draw(simulatedNow);
    },
    dispose() {
      drops = [];
      splashes = [];
      bubbleSprites.clear();
    },
  };
}
